import type { AffinityId } from './affinities'
import type { RarityId } from './rarities'

// Les personnages du jeu, par univers. `kana` = le nom en japonais, écrit à la verticale sur la carte.
// `model` désigne le modèle 3D (public/models) et ses illustrations (src/assets/art) ;
// un personnage sans `model` n'a pas d'illustration fournie : sa carte affiche son nom en japonais à la place.
// Rôles : DPS (frappe fort), Tank (encaisse), Soigneur (soigne). Seules les cartes LR et MR peuvent cumuler deux rôles.
// Dégâts, défense et PV de base (niveau 1) : fixés par la rareté puis répartis selon le rôle (tools/data/gen_roles.py).
export type Role = 'DPS' | 'Tank' | 'Soigneur' | 'DPS / Tank' | 'DPS / Soigneur' | 'Tank / Soigneur'
export const ROLE_KINDS = { dps: 'DPS', tank: 'Tank', soigneur: 'Soigneur', hybride: 'Hybride' } as const
export type RoleKind = keyof typeof ROLE_KINDS
// Famille d'un rôle : sert aux couleurs et au filtre de la collection.
export const roleKind = (role: Role): RoleKind => (role.includes('/') ? 'hybride' : role === 'DPS' ? 'dps' : role === 'Tank' ? 'tank' : 'soigneur')
export type Hero = { id: string; no: number; model?: string; name: string; kana: string; title: string; world: string; role: Role; rarity: RarityId; affinity: AffinityId; atk: number; def: number; hp: number }

